//! Runtime security gateway for AI coding agents building with native dependencies.
//!
//! `sandbox-ffi-layers` intercepts build commands executed by AI coding agents
//! (Claude Code, Codex, OpenCode) and verifies native dependency supply chain
//! before allowing `build.rs`, `proc-macro`, or CFFI execution.

mod cargo_lock;

use anyhow::Result;
use clap::Parser;

#[derive(Parser)]
#[command(name = "sandbox-ffi", version, about)]
struct Cli {
    /// Check Cargo.lock for supply-chain risks (one-shot mode)
    #[arg(short, long)]
    check: bool,

    /// Watch mode: intercept build commands via eBPF (requires root)
    #[arg(short, long)]
    watch: bool,

    /// Path to Cargo.lock (default: ./Cargo.lock)
    #[arg(short, long, default_value = "./Cargo.lock")]
    lockfile: String,

    /// Output format: text, json, sarif
    #[arg(short, long, default_value = "text")]
    format: String,

    /// Exit with code 1 on critical findings
    #[arg(short, long)]
    fail_critical: bool,
}

fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("sandbox_ffi_layers=info")
        .init();

    let args = Cli::parse();

    if args.check {
        let content = std::fs::read_to_string(&args.lockfile)?;
        let packages = cargo_lock::parse_cargo_lock(&content)?;
        let surfaces = cargo_lock::analyze_native_surface(&packages);

        tracing::info!(
            "Analyzed {} packages, {} have native build surface",
            packages.len(),
            surfaces.len()
        );

        for surface in &surfaces {
            let risk = if surface.has_proc_macro {
                "PROC-MACRO"
            } else {
                "BUILD"
            };
            println!(
                "  [{}] {}@{} — {}",
                risk,
                surface.package.name,
                surface.package.version,
                if surface.has_proc_macro {
                    "proc-macro crate"
                } else {
                    "build script dep"
                }
            );
        }

        // Check for known-malicious patterns (proc-macro1 == typosquat)
        let malicious: Vec<_> = packages
            .iter()
            .filter(|p| p.name == "proc-macro1" || p.name == "proc-macro-en")
            .collect();

        if !malicious.is_empty() {
            eprintln!("⚠️  KNOWN-MALICIOUS PACKAGES DETECTED:");
            for m in &malicious {
                eprintln!("  BLOCKED: {}@{}", m.name, m.version);
            }
            if args.fail_critical {
                std::process::exit(1);
            }
        }
    } else if args.watch {
        eprintln!("Watch mode requires eBPF support (coming in v0.2.0)");
        eprintln!("Use --check for one-shot analysis");
        std::process::exit(2);
    } else {
        println!("sandbox-ffi-layers v{}", env!("CARGO_PKG_VERSION"));
        println!("Use --check to analyze a Cargo.lock, or --watch for runtime monitoring");
    }

    Ok(())
}


--- README.md ---
# sandbox-ffi-layers

> Runtime security gateway for AI coding agents building with native dependencies.

`sandbox-ffi-layers` intercepts build commands executed by AI coding agents
(Claude Code, Codex, OpenCode) and verifies native dependency supply chain
before allowing `build.rs`, `proc-macro`, or CFFI execution.

## Problem

In August 2026, the Rust crate `arrayref@0.3.10` was compromised via a typosquat
of `proc-macro2` called `proc-macro1`. The malicious `build.rs` downloaded and
executed a remote payload during `cargo build`. Over 2,285 downloads before removal.

**Existing tools fail because:**
- `cargo audit` only checks known CVEs (new attacks have none)
- Supply-chain scanners (Socket, Phylum) run post-installation
- Agent sandboxes (Eclipse Enclave) don't inspect native build execution

## Solution

`sandbox-ffi-layers` is the first tool to unify:
1. **Agent sandboxing** — intercepts build commands from AI agents
2. **Supply-chain scanning** — checks deps against PhantomDB, OSV, RustSec
3. **Native build detection** — identifies proc-macros, build.rs, CFFI
4. **Runtime enforcement** — blocks BEFORE native code executes

## Installation

```bash
cargo install --locked sandbox-ffi-layers
```

## Usage

```bash
# One-shot check of Cargo.lock
sandbox-ffi --check --lockfile ./Cargo.lock

# With SARIF output for GitHub Code Scanning
sandbox-ffi --check --format sarif --output results.sarif

# Fail on critical findings (CI/CD gate)
sandbox-ffi --check --fail-critical

# Watch mode (requires root, eBPF)
sudo sandbox-ffi --watch
```

## Status

**v0.1.0-alpha** — Cargo.lock parser + proc-macro detection + known-malicious blocklist.

See [PROPOSAL.md](PROPOSAL.md) for full roadmap.

